package schema_test

// Replays Pi's results over the official test suite and the speed cases: for every group and test, the check result and the exact errors (paths, keywords, messages, order) that packages/schema at Pi commit 8ffea8a1 produced.
// testdata/errors-golden.json is generated by testdata/gen-errors.mjs under Node 24 against a checkout of Pi: `node gen-errors.mjs <pi>/packages/schema errors-golden.json`.

import (
	"path/filepath"
	"strings"
	"testing"

	"github.com/MichaelKinsy/PiG/internal/chord/chordjson"
	"github.com/MichaelKinsy/PiG/schema"
	"github.com/MichaelKinsy/PiG/schema/formats"
)

type goldenResult struct {
	check  bool
	errors []schema.ValidationError
}

func decodeResult(t testing.TB, value any) goldenResult {
	t.Helper()
	object := value.(*schema.Object)
	result := goldenResult{check: object.Value("check").(bool)}
	for _, e := range object.Value("errors").([]any) {
		entry := e.(*schema.Object)
		result.errors = append(result.errors, schema.ValidationError{
			Path:    entry.Value("path").(string),
			Keyword: entry.Value("keyword").(string),
			Message: entry.Value("message").(string),
		})
	}
	return result
}

func equalErrors(a, b []schema.ValidationError) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func TestErrorsMatchPi(t *testing.T) {
	golden := readJSON(t, filepath.Join(fixtureRoot, "errors-golden.json")).(*schema.Object)
	schemas := suiteSchemas(t)
	files := map[string]suiteFile{}
	for _, file := range suiteFiles(t) {
		files[file.name] = file
	}
	allFormats := formats.Formats()
	rows := golden.Value("suite").([]any)
	if len(rows) == 0 {
		t.Fatal("empty golden")
	}
	compared := 0
	for _, r := range rows {
		row := r.(*schema.Object)
		name := row.Value("file").(string)
		file := files[name]
		group := file.groups[int(row.Value("group").(float64))]
		options := schema.CompileOptions{Draft: file.draft, Schemas: schemas}
		if strings.Contains(name, "/optional/format/") {
			options.Formats = allFormats
		}
		validator, err := schema.Compile(group.schema, options)
		if want, failed := row.Get("compileError"); failed {
			if err == nil {
				t.Errorf("%s > %s: Pi's compile failed with %q, ours did not", name, group.description, want)
			} else if err.Error() != want.(string) {
				t.Errorf("%s > %s: compile error %q, Pi's %q", name, group.description, err.Error(), want)
			}
			continue
		}
		if err != nil {
			t.Errorf("%s > %s: compile: %v", name, group.description, err)
			continue
		}
		for i, tc := range row.Value("tests").([]any) {
			want := decodeResult(t, tc)
			test := group.tests[i]
			if got := validator.Check(test.data); got != want.check {
				t.Errorf("%s > %s > %s: Check = %v, Pi's %v", name, group.description, test.description, got, want.check)
				continue
			}
			if got := validator.Errors(test.data); !equalErrors(got, want.errors) {
				t.Errorf("%s > %s > %s:\n got %v\nwant %v", name, group.description, test.description, got, want.errors)
			}
			compared++
		}
	}
	t.Logf("compared %d results", compared)
}

func TestSpeedCaseErrorsMatchPi(t *testing.T) {
	golden := readJSON(t, filepath.Join(fixtureRoot, "errors-golden.json")).(*schema.Object)
	for _, c := range golden.Value("cases").([]any) {
		row := c.(*schema.Object)
		t.Run(row.Value("name").(string), func(t *testing.T) {
			validator, err := schema.Compile(row.Value("schema"))
			if err != nil {
				t.Fatal(err)
			}
			for _, input := range []struct{ name, value, result string }{{"valid", "validValue", "valid"}, {"invalid", "invalidValue", "invalid"}} {
				want := decodeResult(t, row.Value(input.result))
				value := row.Value(input.value)
				if got := validator.Check(value); got != want.check {
					t.Fatalf("%s: Check = %v, Pi's %v", input.name, got, want.check)
				}
				if got := validator.Errors(value); !equalErrors(got, want.errors) {
					t.Fatalf("%s:\n got %v\nwant %v", input.name, got, want.errors)
				}
			}
		})
	}
}

func TestHandWrittenCaseErrorsMatchPi(t *testing.T) {
	golden := readJSON(t, filepath.Join(fixtureRoot, "errors-golden.json")).(*schema.Object)
	for i, e := range golden.Value("extras").([]any) {
		row := e.(*schema.Object)
		options := schema.CompileOptions{Draft: schema.Draft(row.Value("draft").(string))}
		if row.Value("formats") == true {
			options.Formats = formats.Formats()
		}
		validator, err := schema.Compile(row.Value("schema"), options)
		if err != nil {
			t.Errorf("case %d %s: compile: %v", i, jsonText(t, row.Value("schema")), err)
			continue
		}
		values := row.Value("values").([]any)
		for j, r := range row.Value("results").([]any) {
			want := decodeResult(t, r)
			if got := validator.Check(values[j]); got != want.check {
				t.Errorf("case %d %s, value %s: Check = %v, Pi's %v", i, jsonText(t, row.Value("schema")), jsonText(t, values[j]), got, want.check)
				continue
			}
			if got := validator.Errors(values[j]); !equalErrors(got, want.errors) {
				t.Errorf("case %d %s, value %s:\n got %v\nwant %v", i, jsonText(t, row.Value("schema")), jsonText(t, values[j]), got, want.errors)
			}
		}
	}
}

func jsonText(t testing.TB, value any) string {
	t.Helper()
	text, err := chordjson.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	return string(text)
}
